   "oneLiner": "先把「智能」这个词拆开：它不是会背答案，而是在没见过的情况里也能做出合理决定；机器学习只是通往智能的一条路线。",
   "core": "智能的工程定义是「在不确定环境里达成目标的能力」，核心指标是**泛化**；机器学习 = 把写不出来的规则交给数据去找。",
