     "body": "神经网络不是新东西（1950s 的感知机就是），但 2012 年 AlexNet 在 ImageNet 上一战成名，靠的是 GPU 训练 + 上百万张标注图片。算法没变多少，燃料变了。\n\n经验规律：模型参数、数据量、算力同步放大时，模型会「涌现」出小模型没有的本领（上下文学习、多步推理）。这就是所谓 scaling law——它不保证一定有效，但过去十年屡试不爽。\n\n对学习者的启示很实际：**先看数据，再谈模型**。数据从哪来、有没有泄漏、类别平不平衡、缺失值怎么处理，这些问题比换一个 fancy 的模型更能决定成败。第 6 集会花整整一集讲数据预处理。",
