     "body": "**语言派**：智能的本质是预测下一个 token。语料足够大、参数足够多，世界知识就被压缩进模型里，推理能力会自然涌现。\n\n**空间派**（李飞飞等）：语言是二手信息，真正的智能需要三维世界的感知与行动——具身智能、世界模型、空间推理。只会说话不等于会做事。\n\n课程的态度是不站队：先把经典机器学习的地基打牢。回归、分类、树模型、聚类、降维，这些是所有路线的共同语言，也是面试和工程里最常考的部分。",
