     "body": "**1–3 集：通识**——搞清楚智能、机器学习、三大范式（监督 / 无监督 / 强化）这些词到底指什么。\n\n**4–8 集：回归主线**——线性回归是第一个模型，梯度下降负责训练，数据预处理决定上限，模型评估告诉你行不行，欠拟合 / 过拟合教你怎么救。这条线是整门课的地基。\n\n**9–10 集：分类**——逻辑回归把回归变成概率，决策树把 if…else 学出来。\n\n**11–12 集：集成**——随机森林（Bagging）和 XGBoost / LightGBM（Boosting），工业界表格数据的王者。\n\n**13–14 集：无监督**——K-Means 聚类、PCA 降维，没有标签时怎么找结构。\n\n**15 集：总结 + 深度学习展望**——把地图收拢，告诉你下一步往哪走。",
