      "lang": "python",
      "title": "手写向量化梯度下降（约 10 行）",
      "src": "import numpy as np\n\n# X: (n, d)，y: (n,)\nX = np.array([[1.0], [2.0], [3.0], [4.0]])\ny = np.array([3.2, 5.6, 6.1, 9.5])\n\nw, b, lr = 0.0, 0.0, 0.05\nfor epoch in range(1000):\n    yh = X @ w + b              # 一次算完所有样本\n    err = yh - y\n    dw = 2 * X.T @ err / len(y) # 梯度也是矩阵乘\n    db = 2 * err.mean()\n    w -= lr * dw\n    b -= lr * db\n\nprint(w, b)                     # 学到的斜率与截距"
