     "body": "线性回归的输出是 (−∞, +∞) 的任意实数，没法当「是垃圾邮件的概率」。硬把 >0.5 当正类也不行：输出 10 和 100 都会被判成正类，但模型不知道「10 有多确定」。\n\nSigmoid 函数 σ(z) = 1/(1+e⁻ᶻ) 把任意实数压到 (0,1)：z=0 时正好 0.5，z 越大越接近 1，z 越小越接近 0。于是 z = wx+b 先算一个「分数」，再变成概率。判正类就用概率 > 0.5，等价于分数 > 0——所以决策边界还是一条直线（高维是超平面）。\n\n损失也要换：MSE 配 Sigmoid 会让梯度里带一项 σ′(z)，z 很偏时 σ′ 趋近 0，梯度几乎不动。改用交叉熵，梯度就变成干净的 (ŷ − y)·x，学得快。第 9 集整集都在讲这个。",
