     "body": "一个完整的最小项目：读入 CSV → 划分训练/测试集 → 标准化特征 → 建模型 → 训练（拟合 w、b）→ 在测试集上算 MSE/RMSE/R² → 调超参 → 对新样本预测。这条流水线第 6、7 集还会展开成完整工程。\n\n它的意义在于**可迁移性**：把 f 从直线换成树、换成神经网络，把 MSE 换成交叉熵，把梯度下降换成 Adam，骨架完全不变。你学会的不是「线性回归」这一个算法，而是「定义模型 → 定义损失 → 优化 → 评估」这套方法论。\n\n面试被问「介绍一下线性回归」，按四段答最清楚：模型结构（ŷ=wx+b）、损失（MSE 及为什么）、优化（梯度下降或闭式解）、评估与局限（线性假设、对离群点敏感、需要特征工程）。",
