     "body": "同一份数据，线性回归和 XGBoost 的差距可能只有 5%；但特征工程做好和做坏，差距往往是 30% 以上。工业界的经验分配是：数据清洗和特征工程占 60%~80% 的时间，模型选型和调参只占一小部分。\n\n三个具体的「上限」：**信息量**——缺了关键特征，神仙模型也预测不准；**样本量**——100 条数据撑不起 50 个特征的模型；**数据质量**——标签错标、重复样本、单位不统一，模型会把噪声当规律学。\n\n本集按一条流水线走：划分 → EDA → 缺失值 → 异常值 → 编码 → 构造/删除 → 缩放 → 封装。顺序很重要，尤其「先划分」这一步，做错了后面全白搭。",
