     "body": "三份数据分工明确：训练集学参数，验证集选模型、调超参，测试集最后只碰一次、给一个诚实的分数。常见比例 7:1.5:1.5 或 6:2:2；数据量小时改用交叉验证（第 7 集）。\n\n**数据泄漏**（leakage）= 训练时不小心用到了测试集或未来的信息。经典案例：先用全量数据算均值和方差做标准化，再划分——测试集的分布信息已经漏进训练；用全量中位数填补缺失；时间序列随机打乱切分，模型看到了「未来」；把 ID、或「是否已放款」这类事后字段直接当特征。\n\n泄漏的症状很典型：离线 R²=0.99，上线后惨不忍睹。排查口诀：**任何在划分前算出来的统计量都要怀疑；任何在预测时刻拿不到的字段都要删。**",
