     "body": "两种检测法。**IQR（箱线图法）**：Q1、Q3 是 25% 和 75% 分位数，IQR = Q3 − Q1，落在 [Q1 − 1.5·IQR, Q3 + 1.5·IQR] 之外算异常。它不假设分布、抗极端值，最常用。**Z-score**：|(x−μ)/σ| > 3 算异常，假设近似正态；但均值和标准差本身会被异常值污染，样本里有极端值时不如 IQR 稳。\n\n处理前先归因：单位写错（把「万」写成「元」）、录入错误（年龄 200）、真实极端（顶层复式 300 m²）。前两种改或删，第三种要保留——它可能是模型在高价段唯一的训练信号。\n\n处理方式：删除（样本多且确认是错）、截断 / winsorize（把超过 1% / 99% 分位的值压到分位点，保住样本量）、变换（log 把长尾压成近似正态）、保留（树模型对单调变换不敏感，本来就抗异常值）。",
