     "h": "特征构造与删除：把业务知识写进数据",
     "lead": "好特征常常是**两个原始列做一次运算**得到的；反过来，冗余、泄漏、常量列必须删。",
     "body": "构造（feature creation）：日期拆成 年/月/日/星期/是否节假日；比率与差值（总价 ÷ 面积 = 单价、房间数 ÷ 面积）；按用户或门店聚合（近 30 天订单数、均值、最近一次时间）；log 变换压长尾；多项式与交互项（面积 × 房龄）。对线性模型尤其重要——它只能表达线性关系，交互项相当于手写非线性。\n\n删除（feature drop）：常数列（方差 0）、近常数列（>99% 都是同一个值）、高缺失列、强冗余列（相关性 >0.95 只留一个）、ID 类列，以及**预测时刻拿不到的事后字段**。特征不是越多越好：噪声特征会稀释信号、增加过拟合风险。\n\n判断标准只有一个：这个特征在「预测发生的那一刻」是否已知、是否与目标有真实关系。可以用树模型的特征重要性或系数显著性做粗筛，但别把特征选择做在测试集上。",
