     "body": "模型在训练时就是奔着「让训练误差最小」去的，所以训练误差天然偏低，甚至能到 0（特征数 ≥ 样本数时，模型可以逐条记住标签）。用训练集 R²=0.98 汇报，相当于让学生用做过十遍的原题考试。\n\n三份数据分工：训练集学参数、验证集选模型和调超参、测试集最后只碰一次做最终报告。最常见的错误是「在测试集上反复试不同模型，挑分数最高的那个」——这时测试集已经参与了你做选择的过程，它实际上变成了验证集，报出来的分数必然偏乐观。\n\n数据不够时（几千条），用 K 折交叉验证代替单独的验证集；测试集仍然要留一份，最后一碰。",
