     "body": "回归任务的基线：ŷ = ȳ（训练集标签均值），不看任何特征，是最笨的模型。但它给出两个重要数字：基线 MSE 恰好等于 y 的方差（因为每条的误差都是 yᵢ − ȳ），基线 R² 恰好是 0。\n\n为什么必须建基线：模型 R²=0.62 听起来不错，但如果业务基线（比如「用去年同期价格」、「用挂牌价打个折」）已经有 0.55，你的模型其实只多解释了 7 个百分点，可能不值得上线。反过来，如果人工估价 RMSE=20 万，你的模型 RMSE=15 万，这才是能讲给人听的进步。\n\n分类任务的基线是「全猜多数类」或「按先验概率随机猜」；时间序列基线是「预测值等于上一个时间点」或「去年同期」。sklearn 的 `DummyRegressor` / `DummyClassifier` 一行就能建。",
