     "body": "MAE = (1/n)Σ|yᵢ−ŷᵢ|。它对每个误差一视同仁，等价于优化「条件中位数」，因此对异常值稳健。缺点是在 0 点不可导，用梯度下降优化时不如 MSE 顺滑（工程上常用 Huber 损失折中：误差小时像 MSE，大时像 MAE）。\n\nR² = 1 − SS<sub>res</sub>/SS<sub>tot</sub>，其中 SS<sub>res</sub>=Σ(y−ŷ)²，SS<sub>tot</sub>=Σ(y−ȳ)²。它回答「模型解释了多少比例的方差」：R²=0.8 表示比全猜均值少犯了 80% 的平方误差。\n\n两个反直觉点：**R² 可以是负数**（模型比全猜均值还差，通常是没调好或测试集分布不同）；**R² 会随数据方差变化**（同样 RMSE=10，在方差大的数据集上 R² 很高，在方差小的数据集上可能接近 0 甚至为负）。所以 R² 适合同一任务内比较，不适合跨任务炫耀。",
