     "body": "三个分数摆在一起就能诊断：训练 R²=0.95、验证 R²=0.60 → 过拟合（把训练集的噪声也背下来了）；训练 0.55、验证 0.54 → 欠拟合（模型太简单，还没学到规律）；训练 0.80、验证 0.78 → 比较健康。\n\n判据不要只看绝对值，要看**差距**（gap），因为数据量小时验证集本身波动就大。配合学习曲线（横轴训练样本量，纵轴训练/验证分数）还能判断「加数据有没有用」：两条曲线还离得远、验证分仍在上升 → 加数据有用；两条曲线贴在一起但都很低 → 该换更复杂的模型或更好的特征。\n\n这一集只负责诊断；怎么治（L1/L2 正则化、早停、更多数据、特征选择）是第 8 集的内容。评估做得扎实，第 8 集的药才吃得对症。",
