     "body": "L2（岭回归）在损失后加 λΣw<sup>2</sup>，效果是权重衰减：所有参数被整体压小、模型输出更平滑，对输入的小扰动不敏感，方差自然下降。L1（Lasso）加 λΣ|w|，不仅压小，还能把一部分权重压到恰好 0，顺带完成特征选择。\n\n几何直觉最能说明差别：约束区域在 L2 下是圆形，在 L1 下是菱形。菱形的顶点落在坐标轴上，损失等高线往外扩时更容易「切」在顶点上，于是某个权重正好为 0；圆的切点一般不在坐标轴上，所以 L2 只把权重整体压小，不做筛选。\n\n为什么抑制过拟合：权重越小，输出对输入的微小变化越不敏感，换一批数据模型也不会剧烈变脸。",
