     "body": "先忘掉算法，想一个日常判断：银行要不要给你批贷款？先问收入是否大于 1 万；是的话再问有没有房；有房就批，没房再看负债率。这一串问题画成图，就是一棵决策树。\n\n它和逻辑回归的区别很好记：逻辑回归用一个公式给所有样本「打一个总分」，树则是把特征空间切成一块块矩形，每块给一个答案。所以树天然能表达「只有年轻 + 高收入才批」这种组合条件，而线性模型必须手动造交叉特征。\n\n树的魅力在于可解释：每条从根到叶的路径都能读成人话，这是它在风控、医疗等场景被偏爱的原因。它既能做分类（叶子取多数类），也能做回归（叶子取平均值）。",
     "tip": "一棵树的三个要素：内部节点是「问题」，分支是「答案」，叶子是「结论」。"
