     "body": "根节点是唯一入口，对应第一个、也是信息量最大的那个问题；内部节点是中间测试，继续往下分裂；叶节点不再分裂，直接输出类别或均值；分支是某个特征的取值（或阈值的一侧）。\n\n从根到叶的最长路径叫深度。深度越大、叶子越多，模型能表达的规则越细，容量越大，也越容易过拟合。\n\n工程上常见的参数都围绕这几个概念：max_depth 限制深度，min_samples_leaf 限制每个叶子的样本数，min_samples_split 限制节点可分裂的最小样本数。它们本质上是在限制树的形状。",
