     "body": "纯度的反面叫「不纯度」。如果节点里正负各 50%，不管怎么猜都只有一半对；如果 100% 是正类，就再也不用问了。所以每次分裂要挑那个「分完之后子节点最纯」的特征。\n\n衡量不纯度有三把常用尺子：熵（来自信息论）、基尼系数（随机抽两个样本、类别不同的概率）、分类误差（1 − 多数类比例，最简单但不够敏感）。ID3 / C4.5 / CART 就是选了不同尺子。\n\n注意「最纯」是加权后的整体最纯，不是某一个子节点最纯。只看一边会选出把数据切得很偏的特征，最后整体没变干净。",
