     "lead": "熵衡量混乱程度：**两类各一半时熵最大（1 bit），全是一类时熵为 0**。",
     "body": "二分类熵 H = −[p·log<sub>2</sub>p + (1−p)·log<sub>2</sub>(1−p)]。p=0.5 时 H=1；p=0.9 时 H≈0.469；p=1 时 H=0。熵越大越乱，越需要继续分裂。\n\n信息增益 = 分裂前的熵 − 分裂后各子集熵的加权平均。它回答「问完这个问题，整体混乱度下降了多少」，增益越大这个特征越值得先问。\n\n用经典天气数据算一遍：14 天里 9 天玩、5 天不玩，H(D)=0.940。按天气分：晴 5 天（2 玩 3 不玩，H=0.971）、阴 4 天（全玩，H=0）、雨 5 天（3 玩 2 不玩，H=0.971），加权后 0.693。信息增益 = 0.940 − 0.693 = 0.247，比湿度（0.152）、风力（0.048）、温度（0.029）都大，所以天气当根节点。",
