     "body": "伪代码三步：① 若当前节点已足够纯、或无特征可用、或样本太少，就返回叶节点；② 否则遍历每个特征，计算分裂后的不纯度下降，选下降最大的那个（及其阈值）；③ 按取值把数据切成几份，对每份递归调用。\n\n停止条件通常包括：节点全属同一类、特征用完、样本数小于阈值、深度达到上限、最佳增益低于阈值。这些条件就是决策树的正则化旋钮。\n\n停止太松，树会长到每个叶子都纯，训练集 100% 正确但验证集崩；停止太紧，模型欠拟合。sklearn 对应参数是 max_depth、min_samples_leaf、min_samples_split、min_impurity_decrease。",
