     "body": "四个候选特征的信息增益分别是：天气 0.247、湿度 0.152、风力 0.048、温度 0.029，所以天气当根，分出晴、阴、雨三支。\n\n阴天分支 4 条全是「玩」，节点已纯，直接变成叶节点。晴天分支 5 条（3 不玩、2 玩），在「湿度」上分：湿度高 3 条全不玩、湿度正常 2 条全玩，两个子节点都纯了，停止。雨天分支 5 条（3 玩、2 不玩），用「风力」分：风大 2 条全不玩、风小 3 条全玩，同样纯了。\n\n最后得到的树在 14 条训练数据上 100% 正确。但停下来想一想：14 条样本长出一棵 3 层树，每个叶子只装 2–3 条数据——这棵树的泛化能力很可能堪忧，这正是下一张卡「剪枝」要处理的问题。",
