     "body": "为什么树这么不稳？因为建树是贪心的：每一步只选当前最优分裂，根节点的选择一旦变，后面整棵树就跟着重画。数据里多一条样本、少一条样本，根节点可能从「天气」换成「湿度」，所有叶子的结论都变。\n\n举个具体例子：把一条原本「玩」的样本改成「不玩」，天气特征的信息增益可能从 0.247 掉到 0.23，湿度从 0.152 升到 0.16，根节点就换人了。模型对训练集过拟合得越深，这种敏感度越高。\n\n解法有两条：让单棵树变简单（剪枝，但会把偏差抬上去）；或者训练很多棵高方差的树，让它们「各错各的」，再取平均——这就是 Bagging 的思路。",
