     "body": "Bootstrap 是「有放回抽样」：每次抽一条样本、记下来、放回去再抽下一条。所以每棵树的训练集里既有重复样本，也会漏掉一部分样本。\n\n漏掉多少可以算：一条样本一次都没被抽中的概率是 (1−1/N)^N，N 很大时趋近 1/e ≈ 0.368。所以每棵树大约只用到 63.2% 的不同样本，剩下 36.8% 成了「袋外样本」——这就是下一张卡 OOB 的来源。\n\n关键公式是集成后的方差：Var = ρσ<sup>2</sup> + (1−ρ)σ<sup>2</sup>/B。B 增大时第二项趋近 0，但第一项 ρσ² 由树之间的相关性 ρ 决定。也就是说，光靠样本随机还不够——树如果长得太像，平均也没用，必须再降相关性。",
