     "body": "样本随机（行随机）已经让每棵树的训练集不同，但还不足以把树「去相关」——如果某个特征特别强，每棵树都会先选它，树就还是长得像。\n\n特征随机（列随机）解决这个问题：每次分裂时，先从 d 个特征里随机抽 m 个，只在这 m 个里挑最优。强特征不是每次都能被抽到，树的结构自然就分化了。常用取值：分类 m = √d，回归 m = d/3（d 是特征总数）。\n\nm 很小 → 每棵树都很弱但差异大，需要更多树；m = d 且只做样本随机 → 退化成普通 Bagging。随机森林和「Bagging + 决策树」的唯一区别，就是这一刀特征随机。",
