     "body": "具体做法：对每一条样本，找出所有「训练时没见过它」的树，让这些树投票，得到这条样本的袋外预测；把所有样本的袋外预测汇总，就是 OOB 误差。\n\n它近似于留一交叉验证，却几乎不额外花成本：训练时顺手就能算，不用再切一份验证集。数据量小的时候特别值——多切 20% 出来心疼，OOB 相当于把这份数据「省」回来了。\n\nsklearn 里开一个开关就行：RandomForestClassifier(oob_score=True)，训练完读 oob_score_。注意样本很少时 OOB 估计会不稳定，调参时最好再配合交叉验证一起看。",
