     "body": "不纯度重要性（也叫 Gini importance）：统计每个特征在所有树的所有分裂里带来的不纯度下降总量，归一化到和为 1。它训练时零成本，但有两个毛病：偏爱取值多的连续 / 高基数特征（分裂机会多），且相关特征之间会「分票」，两个同样重要的特征可能各只拿到一半。\n\n置换重要性（permutation importance）：在 OOB 或验证集上，把某一列的值随机打乱，看模型分数掉多少；掉得越多，这个特征越重要。它更贴近「真实预测贡献」，但计算更贵（每个特征都要重跑一遍），相关特征之间也会互相低估。\n\n实践建议：两个都看，重要结论用置换重要性复核；更不要把特征重要性当因果结论——它只说「模型用得多」，不说「改变它会怎样」。",
