     "body": "优点：准确率稳、对超参数不敏感、不需要特征缩放、能处理非线性和特征交互、对缺失值和异常值有一定鲁棒性、可并行训练、自带 OOB 评估和特征重要性。这些特点让它成为表格任务的第一选择，很多 Kaggle 比赛的第一个强基线就是它。\n\n缺点：模型体积大、预测比单棵树慢；可解释性从「读一条规则」退化到「看重要性排序」；高维稀疏数据（如文本 TF-IDF）往往不如线性模型；回归不能外推；类别极不平衡时仍需要专门处理。\n\n和单棵树对比：方差明显下降、偏差略升、稳定性大幅提升、可解释性下降。和 Boosting 对比：随机森林更不容易过拟合、更好调；Boosting 通常精度更高但更吃调参。",
