      "src": "from sklearn.datasets import load_diabetes\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.ensemble import GradientBoostingRegressor\nfrom sklearn.metrics import mean_squared_error\nimport numpy as np\n\nX, y = load_diabetes(return_X_y=True)\nXtr, Xte, ytr, yte = train_test_split(X, y, test_size=0.2, random_state=0)\n\ngbr = GradientBoostingRegressor(\n    n_estimators=300,      # 树的数量：让早停来定更稳\n    learning_rate=0.05,    # 每棵树的步长（shrinkage）\n    max_depth=3,           # 单棵树深度：GBDT 通常很浅\n    subsample=0.8,         # 每棵树只用 80% 样本\n    random_state=0)\ngbr.fit(Xtr, ytr)\n\npred = gbr.predict(Xte)\nprint('RMSE', np.sqrt(mean_squared_error(yte, pred)))\nprint('实际用了多少棵树', gbr.n_estimators_)\n\n# 换成 XGBoost（参数更丰富，工业界更常用）：\n# from xgboost import XGBRegressor\n# gbr = XGBRegressor(n_estimators=1000, learning_rate=0.05,\n#                    max_depth=3, subsample=0.8,\n#                    early_stopping_rounds=50)"
