     "body": "极端情况：ν = 1、M = 1，等于只训一棵树，就是决策树，欠拟合；ν = 0.001、M = 100000，理论上能拟合得很好，但训练极慢，还容易把噪声也学进去。经验上 ν 取 0.05~0.2、M 用早停自动决定，性价比最高。\n\n举个数：同一份数据，ν = 0.1 时大约 300 棵树达到验证集最优；换成 ν = 0.05 大约要 600 棵，误差曲线最低点差不多但更平滑；ν = 1.0 的话 30 棵就开始过拟合了。\n\n早停（early stopping）是标准做法：留一份验证集，每加一棵树评估一次，连续 N 轮（比如 50 轮）验证误差不再下降就停，并回滚到最好的那一轮。XGBoost / LightGBM 都内置这个能力，能省掉一半调参时间。",
