     "body": "第 0 步：确定 K，随机（最好是 K-Means++）选 K 个初始中心。第 1 步分配：算每个点到 K 个中心的距离，归给最近的那个。第 2 步更新：对每个簇，把中心挪到簇内所有点的坐标均值。这两步重复，直到「没有任何点换簇」或达到最大迭代次数。\n\n为什么一定会停？定义 SSE = Σ<sub>k</sub>Σ<sub>x∈C<sub>k</sub></sub>||x − μ<sub>k</sub>||²。分配这一步固定 μ，每个点选最近中心，SSE 只减不增；更新这一步固定归属，均值就是让 SSE 最小的那个点（对 μ 求导等于 0 可得）。所以 SSE 单调不增且有下界 0，必然收敛。\n\n但收敛到的可能是一个很差的局部最优：换一组初始中心，结果可以完全不同。以为「K-Means 跑完就完事了」是新手最常犯的错。",
