     "body": "看一个反例：一维数据有两团，分别在 0 附近和 100 附近。如果随机初始化把两个中心都放在 0 附近，那么 100 那团永远分不到中心，第二个中心只能把 0 那团切成两半，结果彻底错，而且迭代再怎么跑也救不回来。\n\nK-Means++ 的做法：先随机选第一个中心；之后每个新中心按「到已有最近中心的距离平方」成正比的概率抽取。也就是说，离现有中心越远的点，越容易被选为下一个中心，中心会自然分散开，从根本上减少「两个中心挤在一团」的概率。\n\nsklearn 默认会跑多组不同种子（`n_init`），取 SSE 最小的那组。实践建议：`n_init` 至少 10，数据分布乱就 20~50；固定 `random_state` 方便复现。算法已经比纯随机好很多，但结果仍然是概率性的。",
