     "body": "肘部法：把 K 从 1 试到 10，画 SSE–K 曲线。K 每加 1，SSE 一定下降（更多簇总能拟合得更好），但下降幅度会突然变缓，曲线出现一个「肘部」，拐点之前陡、之后平，那个 K 就是候选。缺点是真实数据的肘部经常不明显。\n\n轮廓系数：对每个点算 a（到本簇其他点的平均距离）和 b（到最近的其他簇的平均距离），s = (b − a)/max(a, b)，范围 −1~1。全样本平均就是轮廓系数，越接近 1 越好：一般 > 0.5 算结构清晰，< 0.25 说明簇之间大量重叠、K 选得不对。\n\n业务约束经常比指标更重要：做用户分层，运营只肯维护 4 个策略组，那就 K = 4；做颜色压缩，16 色调色板就够。另外要记住：**SSE 一定会随 K 下降，不能直接拿 SSE 最小选 K**（K = n 时 SSE 是 0）。",
