      "中心化：每列减均值，PCA 必须先做",
      "协方差矩阵：d×d 对称矩阵，描述特征间的相关结构",
      "特征值分解：特征向量 = 新坐标轴，特征值 = 该轴上的方差",
      "投影：Z = X·V_k，把 n×d 变成 n×k",
