     "body": "例子：特征有「年龄（20~60 岁）」和「年收入（3 万~30 万元）」。收入的方差是年龄的上万倍，协方差矩阵几乎被收入独占，PC1 几乎就是收入轴。这不是数据本身的结构，而是单位选择造成的假象——把收入换成「万元」再算，主成分会立刻变个样。\n\n标准化：z = (x − μ)/σ，让每个特征方差为 1，总方差等于 d，各特征公平竞争。注意标准化要在**划分训练 / 测试之后**，用训练集的 μ、σ 去变换测试集，避免数据泄漏——这一点和 PCA 本身一样，都要放进 Pipeline。\n\n什么时候可以不标准化？同一量纲、同一量级的数据（比如都是像素灰度 0~255、都是同一份问卷的 5 分制）。只要单位不同，就老老实实标准化。",
