     "h": "15 集收成一张地图",
     "lead": "15 集不是 15 个孤立算法，而是**一条主线 + 六个模块**：通识 → 回归 → 分类 → 集成 → 无监督 → 总结。",
     "body": "模块一（1–3 集）通识：什么是智能、机器学习定义、三大范式。模块二（4–8 集）回归主线：线性回归给出模型骨架，梯度下降给出训练方法，数据预处理决定上限，模型评估和过拟合决定「这个结果能不能信」。\n\n模块三（9–10 集）分类：逻辑回归把回归套一层 sigmoid 变成概率，决策树把 if…else 自动学出来。模块四（11–12 集）集成：随机森林（Bagging，并行降方差）、XGBoost / LightGBM / CatBoost（Boosting，串行降偏差）。模块五（13–14 集）无监督：K-Means 分样本、PCA 压特征。模块六（15 集）收网，并望向深度学习。\n\n依赖关系很重要：不懂回归就学不动梯度下降，不懂决策树就学不动随机森林和 GBDT，不懂方差 / 偏差就理解不了集成为什么有效。所以建议按顺序学，跳着学容易「记住名词但不会用」。",
     "fig": "fig-course-map",
     "figCap": "15 集 × 6 模块的依赖地图：后一集几乎都会复用前一集的概念，这也是复习时最好用的索引。",
     "tip": "复习顺序：先看这张地图 → 挑自己最弱的一集回看 → 用一页速查表过公式 → 做自测题查漏。"
