     "lead": "无监督不是监督学习的替代品，它是**探索工具**：聚类找分组、降维找结构、异常检测找离群点。",
     "body": "K-Means 给样本分组（用户分层、商品聚类），它要求先定 K、假设凸簇、对量纲敏感。PCA 把特征压到少数几个方向，用于去相关、加速、可视化。两者经常连用：先 PCA 降维再 K-Means，是处理高维数据的标准组合。\n\n无监督的评估比监督难得多：没有 ground truth，只能靠内部指标（轮廓系数、解释方差率）加上业务判断。所以无监督项目最容易「做得漂亮但没人用」——上线前先想清楚这个分组要驱动什么动作（发券？分层定价？），否则 K 调到 0.6 的轮廓系数也没有意义。\n\n也有把无监督当前置步骤的用法：先用聚类生成伪标签、用 PCA 压缩特征再喂分类器、用异常检测做数据清洗。这时无监督的价值要用下游任务的指标来验证，而不是盯着轮廓系数自嗨。",
