     "body": "数据量小于几千行：先上逻辑回归 / 线性回归或强正则的小树，别一上来就 Boosting。数据量几万到百万行的表格：LightGBM / XGBoost。类别特征多且基数高（用户 ID、商品 ID）：CatBoost 或 LightGBM 原生类别处理。图像、文本、语音、序列：直接深度学习。\n\n可解释性常常是硬约束：金融拒贷、医疗诊断、保险定价往往要求逐特征解释，这时逻辑回归 + WOE 分箱或浅层树是首选；复杂集成只能用 SHAP 做事后解释——能解释，但不是「模型本身可读」。\n\n还要算总成本：训练成本（CatBoost 慢、深度学习要 GPU）、推理延迟（在线服务常要求几十毫秒，树模型比大模型友好）、维护成本（团队会不会调、能不能复现）。一个 95 分但要三个人维护的模型，常常不如 92 分但一个人就能维护的模型。",
