     "body": "从感知机到多层网络：一个神经元就是 sigmoid(wᵀx + b)，跟逻辑回归同构；堆很多层、让每层学不同抽象级别的特征，就是深度学习。反向传播本质上是链式法则版的梯度下降——第 5 集那个「沿负梯度走一小步」的思想一点没变。\n\n三类主流结构：CNN 用卷积核共享权重，擅长图像（局部相关 + 平移不变）；RNN / LSTM 处理序列但难以并行，已被 Transformer 大面积取代；Transformer 用自注意力建模任意位置之间的关系，是今天大模型的地基（GPT、BERT、ViT 都是它的变体）。\n\n边界在哪：数据量大 + 非结构化数据（图像、文本、语音、序列）+ 允许黑箱 + 有算力 → 深度学习；数据小、表格数据、要求可解释、部署资源有限 → 经典 ML 仍然更优。很多真实系统是混合的：深度学习做召回或特征提取，树模型做排序和打分。",
